_NO_LOG_SENTINEL = 'VALUE_SPECIFIED_IN_NO_LOG_PARAMETER'


def _native_no_log_strings(no_log_strings):
    return tuple(to_native(s, errors='surrogate_or_strict') for s in no_log_strings)


def _redact_text(value, no_log_strings):
    was_bytes = isinstance(value, binary_type) and not isinstance(value, text_type)
    text = to_text(value, errors='surrogate_then_replace') if was_bytes else value
    for secret in no_log_strings:
        if secret:
            text = text.replace(secret, '*' * 8)
    return to_bytes(text, errors='surrogate_then_replace') if was_bytes else text


def _copy_container(value):
    try:
        return type(value)()
    except Exception:
        if isinstance(value, Mapping):
            return {}
        if isinstance(value, Set):
            return set()
        return []


def _sanitize_structure(root, secrets, sanitize_mapping_keys=False, ignore_keys=frozenset()):
    """Copy containers and transform scalar strings without using Python recursion."""
    if not isinstance(root, (Mapping, Sequence, Set)) or isinstance(root, (text_type, binary_type)):
        return root

    # Tuples and immutable sets are finalized after their children are visited.
    def make_container(value):
        if isinstance(value, (tuple, frozenset)):
            return []
        return _copy_container(value)

    root_copy = make_container(root)
    stack = [(root, root_copy, None, None)]
    while stack:
        source, destination, iterator, parent_info = stack[-1]
        if iterator is None:
            iterator = iter(source.items()) if isinstance(source, Mapping) else iter(source)
            stack[-1] = (source, destination, iterator, parent_info)
        try:
            item = next(iterator)
        except StopIteration:
            stack.pop()
            completed = destination
            if isinstance(source, tuple):
                try:
                    completed = type(source)(*destination) if hasattr(source, '_fields') else type(source)(destination)
                except Exception:
                    completed = tuple(destination)
            elif isinstance(source, frozenset):
                completed = type(source)(destination)
            if parent_info is None:
                root_copy = completed
            else:
                parent_dest, parent_key = parent_info
                if parent_key is not None:
                    parent_dest[parent_key] = completed
                elif isinstance(parent_dest, list):
                    parent_dest.append(completed)
                else:
                    parent_dest.add(completed)
            continue

        if isinstance(source, Mapping):
            key, value = item
            new_key = _sanitize_key(key, secrets, ignore_keys) if sanitize_mapping_keys else key
            if isinstance(value, (Mapping, Sequence, Set)) and not isinstance(value, (text_type, binary_type)):
                child = make_container(value)
                if isinstance(value, (tuple, frozenset)):
                    # The tuple is inserted when its frame completes.
                    stack.append((value, child, None, (destination, new_key)))
                else:
                    destination[new_key] = child
                    stack.append((value, child, None, None))
            else:
                destination[new_key] = (
                    _redact_text(value, secrets)
                    if not sanitize_mapping_keys and isinstance(value, (text_type, binary_type)) else value
                )
        else:
            value = item
            if isinstance(value, (Mapping, Sequence, Set)) and not isinstance(value, (text_type, binary_type)):
                child = make_container(value)
                if isinstance(value, (tuple, frozenset)):
                    stack.append((value, child, None, (destination, None)))
                else:
                    if isinstance(destination, list):
                        destination.append(child)
                    else:
                        destination.add(child)
                    stack.append((value, child, None, None))
            else:
                transformed = (
                    _redact_text(value, secrets)
                    if not sanitize_mapping_keys and isinstance(value, (text_type, binary_type)) else value
                )
                if isinstance(destination, list):
                    destination.append(transformed)
                else:
                    destination.add(transformed)
    return root_copy


def _sanitize_key(key, secrets, ignore_keys):
    if not isinstance(key, (text_type, binary_type)):
        return key
    native_key = to_native(key, errors='surrogate_then_replace')
    if native_key in ignore_keys or native_key.startswith('_ansible'):
        return key
    if native_key in secrets:
        return _NO_LOG_SENTINEL
    redacted = _redact_text(key, secrets)
    return redacted


def remove_values(value, no_log_strings):
    """Return a copy with sensitive substrings replaced in string values only."""
    secrets = _native_no_log_strings(no_log_strings)
    if isinstance(value, (text_type, binary_type)):
        return _redact_text(value, secrets)
    return _sanitize_structure(value, secrets)


def sanitize_keys(obj, no_log_strings, ignore_keys=frozenset()):
    """Return a copy with sensitive mapping key substrings masked."""
    return _sanitize_structure(obj, _native_no_log_strings(no_log_strings), True, ignore_keys)


